contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMin) public payable {
        uint oldMin = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedMin;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedMin = true;
        } else {
            revertedMin = false;
        }

        assert(revertedMin && c.MinSum() == oldMin);
    }

    receive() external payable {}
}

